import PoolsFilter from '@/components/pools/PoolsFilter'
import useNavigateToLiquidity from '@/hooks/clmm/useNavigateToLiquidity'
import useTutorial from '@/hooks/dlmm/useTutorial'
import useFavoriteDlmmPool from '@/hooks/pool/useFavoriteDlmmPool'
import { GetFavoritePoolListProps } from '@/hooks/pool/useFavoritePool'
import useGetDlmmPoolList from '@/hooks/pool/useGetDlmmPoolList'
import useStatistics from '@/hooks/stats/useStatistics'
import useDlmmPoolsStore from '@/store/pool/useDlmmPoolStore'
import { DlmmApiPoolGroupItem } from '@/types/dlmm'
import { SortDropBlock, TableSortTh, useGlobalToast } from '@cetus/design'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import useWebConfigStore from '@cetus/stores/src/useWebConfigStore'
import { CommonTypeInfo, ToastType, Token } from '@cetus/types'
import { Icon, NoData, Table } from '@cetus/ui-kit'
import H5MapTable from '@cetus/ui-kit/src/components/H5MapTable'
import { cancelBubble, d } from '@cetus/utils'
import { Box, Button, Flex, HStack, Spinner, Text, VStack } from '@chakra-ui/react'
import { useRequest } from 'ahooks'
import { useEffect, useMemo, useRef, useState } from 'react'
import AprTooltip from '../common/aprTooltip'
import FarmingIcon from '../common/FarmingIcon'
import MiningIcon from '../common/MiningIcon'
import Tour from '../common/Tour'
import WarningIcon from '../common/WarningIcon'
import DLMMActions from './DLMMActions'
import DLMMCoinPairInfo from './DLMMCoinPairInfo'
import RewardsBlock from './RewardsBlock'

type sortRule = 'desc' | 'asc'
export type poolListType = {
  label: 'Liquidity' | 'Volume (24H)' | 'Volume (7D)' | 'Fees (24H)' | 'APR (24H)'
  value: 'tvl' | 'vol' | 'vol7d' | 'fees' | 'totalApr'
}

interface FetchPoolsDataProps extends GetFavoritePoolListProps {
  isWatchList?: boolean
  isListLoading?: boolean
}
function DLMMPools({ isRefreshed, handleIsRefreshed }: { isRefreshed: boolean; handleIsRefreshed: (isFreshed: boolean) => void }) {
  const { isTerm } = useWebConfigStore()
  const { getStatistics } = useStatistics()
  const { goLiquidity } = useNavigateToLiquidity()
  const { getDlmmPoolList } = useGetDlmmPoolList()
  const { getFavoritePoolList } = useFavoriteDlmmPool()
  const {
    dlmmPoolRefreshStatus,
    setDlmmPoolRefreshStatus,
    setDlmmPoolListLength,
    tutorialOpen,
    dlmmPoolListLength,
    isDlmmWatchList,
    setIsDlmmWatchList,
    isDlmmAllPools,
    setIsDlmmAllPools,
    isDlmmIncentivizedOnly,
    setIsDlmmIncentivizedOnly,
    setDlmmPoolFavoriteIdsChange,
    dlmmPoolFavoriteIdsChange,
    dlmmPoolFavoriteIds
  } = useDlmmPoolsStore()
  const [params, setParams] = useState<Record<string, any>>({
    is_vaults: false,
    display_all_pools: false,
    has_mining: true,
    has_farming: true,
    no_incentives: true,
    order_by: '-vol',
    limit: 20,
    offset: 0,
    coin_type: '',
    pool: ''
  })

  const [openPoolsGroup, setOpenPoolsGroup] = useState<Record<string, boolean> | undefined>()

  const onParamsChange = (_params: Record<string, any>) => {
    setParams(prev => ({ ...prev, isListLoading: true, ..._params }))
  }

  const onClickIncentiveTypes = (event: React.ChangeEvent<HTMLInputElement>) => {
    onParamsChange({
      offset: 0
    })
    setIsDlmmIncentivizedOnly(event.target?.checked)
    setIsDlmmAllPools(false)
  }

  const handleIsDisplayChecked = (event: React.ChangeEvent<HTMLInputElement>) => {
    onParamsChange({
      offset: 0
    })
    setIsDlmmAllPools(event.target?.checked)
    setIsDlmmWatchList(false)
    setIsDlmmIncentivizedOnly(false)
  }

  const handleIsWatchList = () => {
    onParamsChange({
      offset: 0
    })
    setIsDlmmAllPools(false)
    setIsDlmmWatchList(!isDlmmWatchList)
    setDlmmPoolFavoriteIdsChange(false)
  }

  useEffect(() => {
    // 监听添加移除收藏的操作
    console.log('🚀 ~ useEffect ~ poolFavoriteIds:', dlmmPoolFavoriteIdsChange, dlmmPoolFavoriteIds)
    if (isDlmmWatchList && dlmmPoolFavoriteIdsChange) {
      setDlmmPoolFavoriteIdsChange(false)
      onParamsChange({
        offset: 0
      })
      setIsDlmmWatchList(true)
    }
  }, [dlmmPoolFavoriteIds?.length, dlmmPoolFavoriteIdsChange])

  const timer = useRef<any>(null)
  const handleRefresh = () => {
    console.log('🚀 ~ handleRefresh ~ handleRefresh:')
    console.log('🚀 ~ handleRefresh ~ handleRefresh:')
    handleIsRefreshed(false)
    setDlmmPoolRefreshStatus('pending')
    setCurrentPage(1)
    onParamsChange({ offset: 0, isListLoading: false })
    timer.current = setTimeout(() => {
      console.log('🚀 ~ timer.current=setTimeout ~ poolRefreshStatus:', dlmmPoolRefreshStatus)
      if (dlmmPoolRefreshStatus == 'pending') {
        setDlmmPoolRefreshStatus('timeout')
      }
    }, 10000)
    getStatistics()
  }

  const [selectCoinList, setSelectCoinList] = useState<Token[]>([])
  const onClickSelectCoinList = (tokenInfo: Token) => {
    setSelectCoinList([...selectCoinList, tokenInfo])
  }
  const onDeleteSelectCoinList = (tokenInfo: Token) => {
    setSelectCoinList(selectCoinList.filter(ele => ele?.coin_type !== tokenInfo?.coin_type))
  }

  const pageSize = 20
  const [isLoadMoreLoading, setIsLoadMoreLoading] = useState(false)
  const [sortRule, setSortRule] = useState<sortRule>('desc')
  const [sortBy, setSortBy] = useState<poolListType>({ label: 'Volume (24H)', value: 'vol' })
  const [total, setTotal] = useState(0)
  const [currentPage, setCurrentPage] = useState(1)
  const [list, setList] = useState<Array<DlmmApiPoolGroupItem>>([])
  const [isLoading, setIsLoading] = useState(true)

  useEffect(() => {
    return () => {
      setList([])
    }
  }, [])

  const getPoolList = async (params: any) => {
    const isListLoading = params?.isListLoading ?? true
    const isWatch = isDlmmWatchList
    const coin =
      selectCoinList.length == 2
        ? `${selectCoinList[0]?.coin_type},${selectCoinList[1]?.coin_type}`
        : selectCoinList.length == 1
          ? `${selectCoinList[0]?.coin_type}`
          : ''
    const { offset = 0 } = params
    if (offset == 0) {
      setCurrentPage(1)
    }
    if (Number(offset) >= pageSize) {
      setIsLoadMoreLoading(true)
    } else {
      setIsLoading(isListLoading)
    }
    const _incentiveTypes = isDlmmIncentivizedOnly ? ['mining', 'farming'] : ['mining', 'farming', 'noIncentives']
    const query: Record<string, any> = {
      ...params,
      coin_type: coin,
      display_all_pools: isWatch ? true : (isDlmmAllPools ?? true),
      offset,
      has_mining: _incentiveTypes.includes('mining'),
      has_farming: _incentiveTypes.includes('farming'),
      no_incentives: _incentiveTypes.includes('noIncentives')
    }
    let result: any
    try {
      if (isWatch) {
        query['pools'] = dlmmPoolFavoriteIds?.filter(Boolean)
        result = await getFavoritePoolList(query)
      } else {
        result = await getDlmmPoolList(query)
      }

      if (result) {
        console.log('🚀 ~ fetchDatafetchPoolsData ~ result:', result)
        if (result?.isLocal) {
          setDlmmPoolRefreshStatus('error')
          setList(result?.list)
          setTotal(result.total)
          setDlmmPoolListLength(
            result.list?.reduce(
              (sum, current) =>
                d(sum)
                  .plus(current?.pools?.length || 0)
                  .toString(),
              '0'
            ) || '0'
          )
          setCurrentPage(1)
        } else {
          if (Number(offset) >= pageSize) {
            setList(prev => prev.concat(result.list))
          } else {
            setList(result.list)
          }
          setTotal(result.total)
          setDlmmPoolListLength(
            (
              result.list?.reduce(
                (sum, current) =>
                  d(sum)
                    .plus(current?.pools?.length || 0)
                    .toString(),
                '0'
              ) ||
              '0' ||
              0
            ).toString()
          )
          setDlmmPoolRefreshStatus('success')
        }
        setIsLoading(false)
      }
    } catch (error) {
      console.log('🚀 ~  ~ error:', error)
      if ((error as any)?.list && (error as any)?.list?.length > 0) {
        setDlmmPoolRefreshStatus('error')
        setList((error as any).list)
        setTotal((error as any).total)
        setDlmmPoolListLength('')
        setIsLoading(false)
      }
    }
    setIsLoading(false)
  }

  useRequest(() => getPoolList(params), {
    refreshDeps: [params, selectCoinList, isDlmmWatchList, isDlmmAllPools, isDlmmIncentivizedOnly],
    manual: false,
    debounceWait: 150
  })

  useEffect(() => {
    if (isLoadMoreLoading) {
      setIsLoadMoreLoading(false)
    }
  }, [list?.length])

  const { failedTsToast } = useGlobalToast()

  useEffect(() => {
    console.log('🚀 ~ PoolsContent ~ poolRefreshStatus:', dlmmPoolRefreshStatus)
    if (dlmmPoolRefreshStatus !== 'pending') {
      const info: ToastType = {
        linkLabel: '',
        getShowInfo: () => {
          const info: CommonTypeInfo = {
            toastTitleText:
              dlmmPoolRefreshStatus == 'error' ? 'Request Error' : dlmmPoolRefreshStatus == 'timeout' ? 'Please check the network status.' : ''
          }
          return info
        }
      }
      if (dlmmPoolRefreshStatus == 'success' || dlmmPoolRefreshStatus == 'error') {
        clearTimeout(timer.current)
      }
      if (dlmmPoolRefreshStatus == 'error' || dlmmPoolRefreshStatus == 'timeout') {
        failedTsToast(info)
      }
      handleIsRefreshed(true)
    }
  }, [dlmmPoolRefreshStatus])

  const { isApp } = useWindowWidth()
  const clickSort = (item: poolListType) => {
    console.log('🚀 ~ clickSort ~ item:', item)
    const scrollElement = document.querySelector('.scroll-container') as HTMLElement | null
    scrollElement?.scrollTo({ top: 0, behavior: 'auto' })
    if (isApp) {
      if (item?.value !== sortBy?.value) {
        onParamsChange({ offset: 0, order_by: `-${item?.value}` })
        setSortRule('desc')
        setSortBy(item)
      }
    } else {
      if (item?.value == sortBy?.value) {
        onParamsChange({ offset: 0, order_by: sortRule == 'desc' ? `${item?.value}` : `-${item?.value}` })
        const rule = sortRule == 'desc' ? 'asc' : 'desc'
        setSortRule(rule)
      } else {
        onParamsChange({ offset: 0, order_by: `-${item?.value}` })
        setSortRule('desc')
        setSortBy(item)
      }
    }
  }

  const sortByList = [
    { label: 'Liquidity', value: 'tvl' },
    { label: 'Volume (24H)', value: 'vol' },
    { label: 'Fees (24H)', value: 'fees' },
    { label: 'APR', value: 'totalApr' }
  ]
  const sortByObject = sortByList.reduce((obj: any, item) => {
    obj[item.value] = item
    return obj
  }, {})

  const changeCurrentPage = (current: number) => {
    const pageOffset = current * pageSize
    getPoolList({ ...params, offset: pageOffset })
    setCurrentPage(prev => prev + 1)
  }

  const hasLoadMore = useMemo(() => {
    const currentSize = (currentPage - 1) * pageSize + list?.length
    return dlmmPoolRefreshStatus !== 'error' && Number(total) > currentSize
  }, [total, currentPage, pageSize, dlmmPoolRefreshStatus, list?.length])

  useEffect(() => {
    getStatistics()
    if (timer.current) {
      clearTimeout(timer.current)
      timer.current = null
    }
    return () => {
      // 组件卸载时 列表条数重置
      if (timer.current) {
        clearTimeout(timer.current)
        timer.current = null
      }
    }
  }, [])

  const loadMoreRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    let observer: IntersectionObserver | null = null

    if (!isLoading && loadMoreRef.current) {
      observer = new IntersectionObserver(
        entries => {
          // 使用防抖处理，避免多次触发
          const entry = entries[0]
          if (entry && entry.isIntersecting && hasLoadMore && !isLoadMoreLoading) {
            console.log('🚀 ~ useEffect ~ entry:', entry)
            changeCurrentPage(currentPage)
          }
        },
        { threshold: 0.5, rootMargin: '100px' }
      )
      observer.observe(loadMoreRef.current!)
    }

    // 清理函数
    return () => {
      if (observer) {
        observer.disconnect()
      }
    }
  }, [isLoading, currentPage, hasLoadMore, isLoadMoreLoading])

  const columns = getColumns(sortRule, sortBy, clickSort, sortByObject, isApp)

  const { stepMap, dlmmTutorialStep, onTutorialExit, onTutorialNext, onTutorialPrevious, onStepDuration, showPoolsTutorial } = useTutorial()

  useEffect(() => {
    onStepDuration()
  }, [onStepDuration])

  const onOpenPoolsGroup = (groupId: string, isOpen: boolean) => {
    setOpenPoolsGroup({ [groupId]: isOpen })
  }
  return (
    <>
      <VStack gap="20px" w="100%" background="bg_primary">
        <PoolsFilter
          handleIsDisplayChecked={handleIsDisplayChecked}
          handleIsWatchList={handleIsWatchList}
          onClickIncentiveTypes={onClickIncentiveTypes}
          handleRefresh={handleRefresh}
          selectCoinList={selectCoinList}
          onClickSelectCoinList={onClickSelectCoinList}
          onDeleteSelectCoinList={onDeleteSelectCoinList}
          isRefreshed={isRefreshed}
          isDlmmPools={true}
          isPools={false}
        />
        <Box h="1px" w="100%" bg="border" />
        <VStack w="100%" position="relative" gap="20px">
          {!isLoading && list?.length == 0 ? (
            <NoData
              type="nodata"
              text="No pools found"
              children={
                <Text mt="4px" textAlign="center">
                  Try adjusting your search or filter settings.
                </Text>
              }
            />
          ) : isApp ? (
            <VStack w="100%" gap="4px">
              <HStack w="100%" justify="space-between">
                <Text fontSize="24px" color="text_caption">
                  Pools
                </Text>
                <SortDropBlock
                  sortText="Sort by"
                  minW="180px"
                  currentSort={sortBy}
                  sortByList={sortByList}
                  onSortByChange={clickSort as any}
                  xlinkHref={sortRule == 'desc' ? '#icon-icon_sort2' : '#icon-icon_sort_asc1'}
                  iconOnClick={() => {
                    onParamsChange({ offset: 0, order_by: sortRule == 'desc' ? `${sortBy?.value}` : `-${sortBy?.value}` })
                    const rule = sortRule == 'desc' ? 'asc' : 'desc'
                    setSortRule(rule)
                  }}
                />
              </HStack>
              <H5MapTable<any>
                rowKey="id"
                dataSource={list}
                columns={columns}
                loading={isLoading}
                itemSkeletonLength={7}
                itemHeight="30px"
                rowStyle={(_, index) => ({
                  w: '100%',
                  p: '0px',
                  mt: '0px'
                })}
                onRowClick={item => {
                  goLiquidity(`/clmm?poolAddress=${item.poolAddress}`, item)
                }}
              />
            </VStack>
          ) : isLoading ? (
            <Table<any>
              rowKey="id"
              columns={columns}
              dataSource={list}
              skeletonLength={10}
              loading={true}
              rowStyle={{ h: '80px', cursor: 'pointer' }}
            />
          ) : (
            <VStack w="100%" gap="0">
              <Box
                as="div"
                display="grid"
                w="1160px"
                gridTemplateColumns="minmax(0px, 3.48fr) minmax(0px, 1.5fr) minmax(0px, 1.5fr) minmax(0px, 1.3fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(142px, 1.72fr)"
                h="36px"
                columnGap="12px"
                p="0 16px"
              >
                {columns?.map((col, index) => (
                  <Flex key={col.key} as="div" align="center" justify={index === 0 ? 'flex-start' : 'flex-end'}>
                    {col.title}
                  </Flex>
                ))}
              </Box>
              <Box w="100%">
                {list?.map((item, index) => {
                  return (
                    <PoolsItem
                      key={item?.id}
                      item={item}
                      columns={columns}
                      goLiquidity={goLiquidity}
                      sort={index}
                      tutorialOpen={tutorialOpen}
                      isOpen={openPoolsGroup?.[item?.id]}
                      onOpen={onOpenPoolsGroup}
                    />
                  )
                })}
              </Box>
            </VStack>
          )}
          {d(dlmmPoolListLength).gt(d(params?.offset).plus(1).mul(pageSize)) && (
            <Box ref={loadMoreRef}>{isLoadMoreLoading ? <Spinner size="sm" color="text_caption" /> : ''}</Box>
          )}
        </VStack>
      </VStack>
      {showPoolsTutorial && (
        <Tour
          isOpen={showPoolsTutorial}
          step={stepMap[dlmmTutorialStep]}
          onExit={onTutorialExit}
          onNext={() => onTutorialNext(list?.[0]?.list?.[0]?.id)}
          onPrev={onTutorialPrevious}
          poolsLength={dlmmPoolListLength}
          isPoolLoading={isLoading}
        />
      )}
    </>
  )
}

const getColumns = (sortRule: string, sortBy: poolListType, clickSort: (value: poolListType) => void, sortByObject: any, isApp: boolean) => {
  return [
    {
      title: <Text fontSize="14px">Pools</Text>,
      key: 'pool',
      thConfig: {
        w: '30%'
      },
      showLabel: false,
      render: (item: any, hasFee: boolean, isParent?: boolean) => {
        return (
          <HStack pl="0">
            <DLMMCoinPairInfo
              poolInfo={item}
              symbolEllipsesDecimals={10}
              hasFee={hasFee}
              symbolFontSize={isParent ? '16px' : '14px'}
              imgBoxStyle={isParent ? { w: '32px', h: '32px' } : { w: '28px', h: '28px' }}
            />
            {item?.haveFarming && <FarmingIcon />}
            {item?.haveMining && <MiningIcon />}
            <WarningIcon coinTypeA={item?.coin_type_a} coinTypeB={item?.coin_type_b} />
          </HStack>
        )
      }
    },
    {
      title: (
        <TableSortTh labelInfo={sortByObject['tvl']} sortRule={sortRule} sortBy={sortBy} clickSort={(value: poolListType) => clickSort(value)} />
      ),
      key: 'tvlDisplay'
    },
    {
      title: (
        <TableSortTh labelInfo={sortByObject['vol']} sortRule={sortRule} sortBy={sortBy} clickSort={(value: poolListType) => clickSort(value)} />
      ),
      key: 'volume24Display'
    },
    {
      title: (
        <TableSortTh labelInfo={sortByObject['fees']} sortRule={sortRule} sortBy={sortBy} clickSort={(value: poolListType) => clickSort(value)} />
      ),
      key: 'fees24Display'
    },
    {
      title: <Text textAlign="right">Rewards</Text>,
      key: 'rewards',
      hidden: ({ miningRewardList, farmsRewarderList }: { miningRewardList: any; farmsRewarderList: any }) => {
        return miningRewardList && miningRewardList?.length <= 0 && farmsRewarderList && farmsRewarderList?.length <= 0
      },
      render: ({ miningRewardList, farmsRewarderList }: { miningRewardList: any; farmsRewarderList: any }) => {
        return <RewardsBlock miningRewardList={miningRewardList} farmsRewarderList={farmsRewarderList} />
      }
    },
    {
      title: (
        <TableSortTh
          labelInfo={sortByObject['totalApr']}
          sortRule={sortRule}
          sortBy={sortBy}
          tooltip={{
            content:
              'Estimated based on trading activity in the past 24 hours plus mining and farming rewards. For pool groups, the displayed APR represents the highest value among active pools in that category'
          }}
          clickSort={(value: poolListType) => clickSort(value)}
          justifyContent="flex-end"
        />
      ),
      key: 'apr24h',
      render: (item: any) => {
        return item?.totalApr ? (
          <Text color="text_highlight" fontWeight="500">
            {item?.totalApr}
          </Text>
        ) : (
          <AprTooltip poolInfo={item} placement={isApp ? 'auto-start' : 'top'} />
        )
      }
    },
    {
      title: <Text textAlign="right">Actions</Text>,
      showLabel: false,
      key: 'actions',
      render: (item: any) => {
        return (
          <Box>
            <DLMMActions poolInfo={item} />
          </Box>
        )
      }
    }
  ]
}

const PoolsItem = ({
  item,
  columns,
  goLiquidity,
  sort,
  tutorialOpen,
  isOpen = false,
  onOpen
}: {
  item: DlmmApiPoolGroupItem
  columns: any[]
  goLiquidity: (url: string, poolApiInfo: any) => void
  sort?: number
  tutorialOpen?: boolean
  isOpen?: boolean
  onOpen: (groupId: string, isOpen: boolean) => void
}) => {
  const [showAll, setShowAll] = useState(false)
  console.log(item, 'poolsItem')
  const onExpand = (e: any) => {
    cancelBubble(e)
    onOpen(item?.id, !!!isOpen)
  }
  const onShowAll = (e: any) => {
    cancelBubble(e)
    setShowAll(!showAll)
  }

  const allData = item?.list
  const lessData = item?.list?.slice(0, 3)

  useEffect(() => {
    if (sort === 0 && tutorialOpen) {
      onOpen(item?.id, true)
    } else {
      onOpen(item?.id, false)
    }
  }, [sort, tutorialOpen])
  const { isApp } = useWindowWidth()
  return (
    <VStack
      border="1px solid"
      borderColor={isOpen ? 'border' : 'transparent'}
      borderRadius="12px"
      gap="0"
      bg={isOpen ? 'bg_secondary' : 'transparent'}
      className="dlmm-tutorial-step-1"
      mb={isOpen ? '12px' : '0'}
    >
      <Box
        pos="relative"
        onClick={onExpand}
        cursor="pointer"
        _hover={{
          '.dlmm_action': {
            svg: { fill: 'text_caption' },
            p: { color: 'text_caption' }
          },
          bg: isApp ? 'auto' : 'primary_opacity.10',
          borderRadius: '12px'
        }}
        as="div"
        display="grid"
        w="100%"
        h="76px"
        p="0 12px"
        borderRadius="12px 12px 0 0"
        columnGap="12px"
        bg={isOpen ? 'white_color_opacity.5' : 'transparent'}
        gridTemplateColumns="minmax(0px, 3.48fr) minmax(0px, 1.5fr) minmax(0px, 1.5fr) minmax(0px, 1.3fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(142px, 1.72fr)"
      >
        {isOpen && (
          <Box
            position="absolute"
            top="76px"
            left="28px"
            h={`${d(60)
              .mul(showAll ? allData?.length - 0.5 : lessData?.length - 0.5)
              .plus(9)
              .toString()}px`}
            w="1px"
            bg="border"
          />
        )}

        {columns?.map((col, index) => (
          <Flex align="center" key={col.key} justify={index === 0 ? 'flex-start' : 'flex-end'}>
            {col?.key === 'actions' ? (
              <Button variant="unstyled" display="flex" gap="4px" bg="transparent" className="dlmm_action">
                <Text fontWeight="500" fontSize="13px" color={isOpen ? 'text_caption' : 'text_paragraph'}>
                  {item?.list?.length} {item?.list?.length > 1 ? 'Pools' : 'Pool'}
                </Text>
                <Icon
                  xlinkHref="#icon-icon_arrow"
                  transform={isOpen ? 'rotate(-180deg)' : 'rotate(0deg)'}
                  transition="transform 0.5s"
                  fontSize="12px"
                />
              </Button>
            ) : col?.render ? (
              col?.render(item, false, true)
            ) : (
              <Text fontSize="14px" fontWeight="500" color="text_caption">
                {item?.[col?.key] || '--'}
              </Text>
            )}
          </Flex>
        ))}
      </Box>
      {isOpen && (
        <VStack w="100%" gap="8px">
          <Box h="1px" />
          <VStack w="100%" gap="0px">
            {(showAll ? allData : lessData).map((i, index) => {
              return (
                <Box w="100%" p="0 8px" borderRadius="12px" pos="relative" key={i.poolId}>
                  <Box w="100%" h="60px" pl="32px">
                    <Box
                      className="dlmm-tutorial-step-2"
                      as="div"
                      display="grid"
                      w="100%"
                      // bg="text_highlight_opacity.10"
                      borderRadius="16px"
                      p="0 6px"
                      onClick={() => goLiquidity(`/dlmm?poolId=${i.poolId}`, item)}
                      cursor="pointer"
                      _hover={{ bg: 'primary_opacity.10' }}
                      columnGap="12px"
                      gridTemplateColumns="minmax(0px, 3.15fr) minmax(0px, 1.5fr) minmax(0px, 1.5fr) minmax(0px, 1.3fr) minmax(90px, 1fr) minmax(90px, 1fr) minmax(142px, 1.72fr)"
                    >
                      {columns?.map((col, index) => (
                        <Flex align="center" key={col.key} justify={index === 0 ? 'flex-start' : 'flex-end'}>
                          {col?.render ? (
                            col?.render(i, true)
                          ) : (
                            <Text fontSize="14px" fontWeight="500" color="text_caption">
                              {i?.[col?.key] || '--'}
                            </Text>
                          )}
                        </Flex>
                      ))}
                    </Box>
                  </Box>
                  <Box pos="absolute" w="12px" h="1px" bg="border" top="50%" left="28px" />
                </Box>
              )
            })}
          </VStack>
        </VStack>
      )}
      {allData?.length > 3 && isOpen ? (
        <Button
          h="44px"
          variant="unstyled"
          onClick={onShowAll}
          display="flex"
          gap="4px"
          cursor="pointer"
          _hover={{
            p: {
              color: 'primary'
            },
            svg: {
              fill: 'primary'
            }
          }}
        >
          <Text fontSize="12px">{showAll ? 'Show Less' : 'Show All'}</Text>
          <Icon xlinkHref="#icon-icon_arrow" transform={showAll ? 'rotate(180deg)' : 'rotate(0deg)'} fontSize="12px" />
        </Button>
      ) : (
        <Box h="9px" />
      )}
    </VStack>
  )
}
export default DLMMPools
