import useNotifiSubscription from '@/hooks/notifi/useNotifiSubscription'
import usePositionList from '@/hooks/position/usePositionList'
import useStatistics from '@/hooks/stats/useStatistics'
import useDlmmPositionStore from '@/store/dlmm-position'
import usePoolsStore from '@/store/pool'
import usePositionStore from '@/store/position'
import { Block } from '@cetus/design'
import { useRpcListener } from '@cetus/hooks'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import useWindowWidth from '@cetus/hooks/src/useWindowWidth'
import { useAccountStore } from '@cetus/stores'
import useNotifiStore from '@cetus/stores/src/notifi'
import { Token } from '@cetus/types'
import { Icon, NoData } from '@cetus/ui-kit'
import { d } from '@cetus/utils'
import { extractStructTagFromType, fixCoinType } from '@cetusprotocol/common-sdk'
import { Box, HStack, Text, VStack } from '@chakra-ui/react'
import { useEffect, useMemo, useState } from 'react'
import PoolsFilter, { PositionTypes } from '../../pools/PoolsFilter'
import LiquidityAndYield from './LiquidityAndYield'
import PoolItem from './PoolItem'
import PositionListLoading from './PositionListLoading'

function PositionsContent({ isRefreshed, handleIsRefreshed }: { isRefreshed: boolean; handleIsRefreshed: (isFreshed: boolean) => void }) {
  const { getStatistics } = useStatistics()
  const { fetchTokenPrices } = useTokenPrice()
  const { currentAccount, onWalletModal } = useAccountStore()
  const { getPositionBaseList, getPosRelatedData } = usePositionList()
  const {
    posRewardsData,
    farmsPosRewardsData,
    posBaseList,
    showPosListLength,
    setShowPosListLength,
    setMyPosYieldValue,
    posBaseListLoading,
    posBaseListGroupByPool
  } = usePositionStore()
  const { dlmmPosBaseList, dlmmPosPoolsRelatedData, dlmmPosPoolsOriginalData, dlmmPosBaseListGroupByPool } = useDlmmPositionStore()
  const [showPosListGroupByPool, setShowPosListGroupByPool] = useState<any>([])
  const { getNotifiPositionTransfer } = useNotifiSubscription()
  const { isApp } = useWindowWidth()
  const totalPositionList = [...posBaseList, ...dlmmPosBaseList]

  const [positionTab, setPositionTab] = useState<PositionTypes>('All')

  const handleRefresh = () => {
    console.log('🚀 ~ handleRefresh ~ handleRefresh:')
    handleIsRefreshed(false)
    setMyPosYieldValue('')
    getStatistics()
    refreshTokenPrice()
    if (currentAccount?.address) {
      handleGetPositionList(currentAccount?.address)
    }
    setTimeout(() => {
      handleIsRefreshed(true)
    }, 1000)
  }
  useRpcListener({
    onRpcChange: () => {
      if (currentAccount?.address) {
        handleGetPositionList(currentAccount?.address)
      }
    }
  })
  const [selectCoinList, setSelectCoinList] = useState<Token[]>([])
  const onClickSelectCoinList = (tokenInfo: Token) => {
    console.log('🚀 ~ onClickIncentiveTypes ~ tokenInfo:', tokenInfo)
    setSelectCoinList(prev => [...prev, tokenInfo])
  }
  const onDeleteSelectCoinList = (tokenInfo: Token) => {
    console.log('🚀 ~ onClickIncentiveTypes ~ tokenInfo:', tokenInfo)
    setSelectCoinList(prev => prev.filter(ele => ele?.coin_type !== tokenInfo?.coin_type))
  }
  useEffect(() => {
    setMyPosYieldValue('')
    if (currentAccount?.address) {
      console.log('🚀 ~ useEffect ~ currentAccount?.address:', currentAccount?.address)
      handleGetPositionList(currentAccount?.address)
    } else {
      setShowPosListLength({})
    }
  }, [currentAccount?.address])

  const handleGetPositionList = async (walletAddress: string) => {
    await getPositionBaseList(walletAddress)
  }

  const { notifiClient, notifiSources } = useNotifiStore()
  useEffect(() => {
    getNotifiPositionTransfer(totalPositionList, notifiClient, notifiSources)
  }, [totalPositionList, notifiClient, notifiSources])

  // 切换tab
  const handleChangePositionTab = (tab: PositionTypes) => {
    setPositionTab(tab)
    handleFilterGroupPool(tab)
  }

  useEffect(() => {
    handleFilterGroupPool(positionTab)
  }, [selectCoinList, posBaseListGroupByPool, dlmmPosBaseListGroupByPool])

  const handleFilterGroupPool = (tab: PositionTypes) => {
    let originData = {}
    if (tab == 'All') {
      originData = { ...posBaseListGroupByPool, ...dlmmPosBaseListGroupByPool }
    } else if (tab == 'CLMM') {
      originData = { ...posBaseListGroupByPool }
    } else if (tab == 'DLMM') {
      originData = { ...dlmmPosBaseListGroupByPool }
    }
    const firstTokenAddress = selectCoinList[0]?.coin_type ? fixCoinType(selectCoinList[0]?.coin_type) : undefined
    const lastTokenAddress = selectCoinList[1]?.coin_type ? fixCoinType(selectCoinList[1]?.coin_type) : undefined

    console.log(
      {
        originData,
        firstTokenAddress
      },
      'originData'
    )

    const filterArr = Object.values(originData).filter((filterItem: any) => {
      if (firstTokenAddress && lastTokenAddress) {
        return (
          (fixCoinType(filterItem.tokenA.coin_type) == firstTokenAddress && fixCoinType(filterItem.tokenB.coin_type) == lastTokenAddress) ||
          (fixCoinType(filterItem.tokenA.coin_type) == lastTokenAddress && fixCoinType(filterItem.tokenB.coin_type) == firstTokenAddress)
        )
      } else if (firstTokenAddress) {
        return fixCoinType(filterItem.tokenA.coin_type) == firstTokenAddress || fixCoinType(filterItem.tokenB.coin_type) == firstTokenAddress
      } else {
        return filterItem
      }
    })
    setShowPosListGroupByPool(filterArr)
    const positionKeys = Object.keys(isExpendPositionMap)
    filterArr?.forEach(item => {
      const poolAddress = item?.dlmmPoolAddress || item?.clmmPoolAddress
      if (!positionKeys.includes(poolAddress)) {
        setIsExpendPosition(poolAddress, true)
      }
    })
    const clmm_position_count = Object.values(posBaseListGroupByPool)
      .filter((item: any) => item.poolType == 'clmm')
      .reduce((sum: number, item: any) => {
        return sum + (item.list ? item.list.length : 0)
      }, 0)
    const dlmm_position_count = Object.values(dlmmPosBaseListGroupByPool)
      .filter((item: any) => item.poolType == 'dlmm')
      .reduce((sum: number, item: any) => {
        return sum + (item.list ? item.list.length : 0)
      }, 0)

    if (currentAccount?.address) {
      setShowPosListLength({
        clmm_position_count,
        dlmm_position_count
      })
    } else {
      setShowPosListLength({})
    }
  }

  // 刷新token价格
  const refreshTokenPrice = () => {
    const list: any = []
    if (totalPositionList?.length > 0) {
      totalPositionList.map(item => {
        list.push(extractStructTagFromType(item?.coinTypeA).full_address)
        list.push(extractStructTagFromType(item?.coinTypeB).full_address)
        const currentPosData = item?.posType == 'clmm' ? posRewardsData[item?.posId] || [] : posRewardsData[item?.id] || []
        const currentPosFarmsData = farmsPosRewardsData[item?.id] || []
        const rewardsArr = currentPosData.concat(currentPosFarmsData)
        rewardsArr?.map((reward: any) => {
          if (d(reward?.display_amount_owed).gt(0)) {
            list.push(extractStructTagFromType(reward?.token?.coin_type).full_address)
          }
        })
      })
      const tokenArr: any = Array.from(new Set(list))
      console.log('🚀 ~ refreshTokenPrice ~ list:', totalPositionList, list, tokenArr)
      fetchTokenPrices(tokenArr)
    }
  }

  useEffect(() => {
    refreshTokenPrice()
  }, [totalPositionList?.length, posRewardsData])

  useEffect(() => {
    getStatistics()
    // 组件卸载时 列表条数重置
    return () => {
      setShowPosListLength({})
    }
  }, [])
  useEffect(() => {
    if (posBaseListLoading) {
      setShowPosListLength({})
    }
  }, [posBaseListLoading])

  const [openExpendList, setOpenExpendList] = useState()

  const { isExpandAllPosition, setIsExpandAllPosition, isExpendPositionMap, setIsExpendPosition, clearIsExpendPositionMap } = usePoolsStore()

  const hasOneExpand = useMemo(() => {
    const hasOpen = Object.values(isExpendPositionMap).some(item => item)
    // 只要有一个是展开状态，则全局按钮 可操作收起全部
    return hasOpen
  }, [isExpendPositionMap])

  useEffect(() => {
    const isExpandAll = Object.values(isExpendPositionMap).every(item => item)
    setIsExpandAllPosition(isExpandAll)
  }, [isExpendPositionMap])

  useEffect(() => {
    return () => {
      clearIsExpendPositionMap()
    }
  }, [])

  return (
    <VStack gap="16px" w="100%">
      <LiquidityAndYield />
      <PoolsFilter
        isPools={false}
        handleRefresh={handleRefresh}
        selectCoinList={selectCoinList}
        onClickSelectCoinList={onClickSelectCoinList}
        onDeleteSelectCoinList={onDeleteSelectCoinList}
        positionCountObj={showPosListLength}
        handleChangePositionTab={handleChangePositionTab}
      >
        {!isApp && showPosListGroupByPool?.length > 0 && (
          <Block
            w={{
              base: '35%',
              lg: 'unset'
            }}
            borderRadius="12px"
            p={isApp ? '0 6px 0 8px' : '0px 10px 0 8px'}
            h="40px"
          >
            <HStack
              h="100%"
              justify="space-between"
              sx={{
                cursor: 'pointer',
                _hover: {
                  svg: {
                    fill: 'text_caption'
                  },
                  p: {
                    color: 'text_caption'
                  }
                }
              }}
              onClick={() => {
                const newExpandState = !hasOneExpand
                const newMap = Object.keys(isExpendPositionMap).reduce(
                  (acc, key) => {
                    acc[key] = newExpandState
                    return acc
                  },
                  {} as Record<string, boolean>
                )
                Object.entries(newMap).forEach(([poolAddress, status]) => {
                  setIsExpendPosition(poolAddress, status)
                })
              }}
            >
              {hasOneExpand ? <Icon xlinkHref="#icon-icon_collapse" /> : <Icon xlinkHref="#icon-icon_expand" />}
              <Text whiteSpace="nowrap">{hasOneExpand ? 'Collapse All' : 'Expand All'}</Text>
            </HStack>
          </Block>
        )}
      </PoolsFilter>
      <Box h="1px" w="100%" bg="border" />

      {!currentAccount?.address ? (
        <NoData type="nowallet" onboard={() => onWalletModal(true)} />
      ) : posBaseListLoading ? (
        [{}, {}, {}, {}].map((item, index) => {
          return <PositionListLoading key={index} />
        })
      ) : showPosListGroupByPool?.length > 0 ? (
        showPosListGroupByPool.map((item, index) => {
          return <PoolItem key={item?.clmmPoolAddress || item?.dlmmPoolAddress} poolInfo={item} />
        })
      ) : (
        <NoData type="nodata" text="No liquidity positions" />
      )}
    </VStack>
  )
}

export default PositionsContent
